'use client';

import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent } from 'react';
import ApiRichText from './ApiRichText';
import AutoSlider from './AutoSlider';
import SlidingTabList from './SlidingTabList';
import StepSlider from './StepSlider';
import InternationalCountryMap from './InternationalCountryMap';
import { usePageMenuOpen } from './LocalPageShell';
import { SITE_BASE } from './site-base';
import PageTitleStrip from './PageTitleStrip';
import { resolveSiteHref } from './site-routes';
import { requestInternationalContent, type InternationalBlock, type InternationalContent, type InternationalPhoto, type InternationalUpdate } from './international-page-data';
import { hostelVideo, type HostelVideo } from './hostel-page-data';
import styles from './InternationalPage.module.css';

// Existing supplied artwork travels with this component: the server currently
// returns 404 for the separate international-page asset directory. API photos stay live.
const internationalArtwork: Record<string, string> = {
  "campus-poster.jpeg": "data:image/jpeg;base64,",
  "director-poster.jpeg": "data:image/jpeg;base64,",
  "hero.jpeg": "data:image/jpeg;base64,",
};
const asset = (name: string) => internationalArtwork[name] || `${SITE_BASE}/assets/international-page/${name}`;
type Modal = { kind: 'photos'; photos: InternationalPhoto[]; index: number } | { kind: 'video'; video: HostelVideo } | { kind: 'content'; item: InternationalUpdate };
const Play = () => <span className={styles.play} aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 4v16l13-8Z" /></svg></span>;

function Preview({ value, close, change }: { value: Modal; close: () => void; change: (index: number) => void }) {
  const element = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null, overflow = document.body.style.overflow;
    element.current?.showModal(); document.body.style.overflow = 'hidden';
    return () => { element.current?.close(); document.body.style.overflow = overflow; previous?.focus({ preventScroll: true }); };
  }, []);
  const title = value.kind === 'photos' ? value.photos[value.index].alt || 'International photo gallery' : value.kind === 'video' ? value.video.title : value.item.title;
  const video = value.kind === 'video' ? value.video : value.kind === 'content' ? value.item.video : null;
  return <dialog ref={element} className={styles.dialog} aria-label={title} data-lenis-prevent="true"
    onCancel={event => { event.preventDefault(); close(); }} onClick={event => { if (event.target === event.currentTarget) close(); }}
    onKeyDown={event => {
      if (value.kind === 'photos' && ['ArrowLeft', 'ArrowRight'].includes(event.key)) {
        event.preventDefault(); change((value.index + (event.key === 'ArrowRight' ? 1 : -1) + value.photos.length) % value.photos.length);
      }
    }}>
    <div className={styles.dialogInner}>
      <button type="button" autoFocus className={styles.close} aria-label="Close preview" onClick={close}>×</button>
      {value.kind === 'photos' ? <>
        <img className={styles.fullPhoto} src={value.photos[value.index].src} alt={title} />
        <div className={styles.photoControls}>
          <button type="button" aria-label="Previous photo" onClick={() => change((value.index - 1 + value.photos.length) % value.photos.length)}>‹</button>
          <span>{title}<small>{value.index + 1} / {value.photos.length}</small></span>
          <button type="button" aria-label="Next photo" onClick={() => change((value.index + 1) % value.photos.length)}>›</button>
        </div>
      </> : value.kind === 'content' && <><h2>{title}</h2><ApiRichText html={value.item.html} scrollTables /></>}
      {video && (/\.(mp4|webm)(?:$|[?#])/i.test(video.src)
        ? <video className={styles.videoPlayer} src={video.src} poster={video.poster} controls autoPlay playsInline />
        : <iframe className={styles.videoPlayer} src={`${video.src}${video.src.includes('?') ? '&' : '?'}autoplay=1&rel=0`} title={video.title} allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerPolicy="strict-origin-when-cross-origin" allowFullScreen />)}
      {value.kind === 'video' && <p className={styles.videoCaption}>{title}</p>}
    </div>
  </dialog>;
}

function keyboardTabs(event: KeyboardEvent<HTMLElement>, active: number, count: number, select: (index: number) => void) {
  if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return;
  event.preventDefault();
  const index = event.key === 'Home' ? 0 : event.key === 'End' ? count - 1 : (active + (event.key === 'ArrowRight' ? 1 : -1) + count) % count;
  select(index); event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]')[index]?.focus({ preventScroll: true });
}

function ContentTabs({ items, label, className = '' }: { items: InternationalBlock[]; label: string; className?: string }) {
  const [active, setActive] = useState(0), id = useId();
  if (!items.length) return null;
  const index = Math.min(active, items.length - 1), item = items[index];
  return <div className={`${styles.tabSection} ${className}`}>
    <SlidingTabList className={styles.tabs} activeKey={index} aria-label={label} onKeyDown={event => keyboardTabs(event, index, items.length, setActive)}>
      {items.map((tab, i) => <button type="button" role="tab" id={`${id}-tab-${i}`} aria-controls={`${id}-panel`} aria-selected={index === i} tabIndex={index === i ? 0 : -1} key={i} onClick={() => setActive(i)}>{tab.title}</button>)}
    </SlidingTabList>
    <div role="tabpanel" id={`${id}-panel`} aria-labelledby={`${id}-tab-${index}`} tabIndex={0} className={styles.tabPanel} key={index}>
      <ApiRichText html={item.html} scrollTables />
      {item.href && <a className={styles.readMore} href={resolveSiteHref(item.href, item.title)}>Read more <span aria-hidden="true">›</span></a>}
    </div>
  </div>;
}

function PhotoGallery({ photos, paused, preview }: { photos: InternationalPhoto[]; paused: boolean; preview: (index: number) => void }) {
  const [active, setActive] = useState(2), [playing, setPlaying] = useState(true), [visible, setVisible] = useState(false), [held, setHeld] = useState(false);
  const root = useRef<HTMLDivElement>(null), pointer = useRef<{ x: number; y: number; id: number } | null>(null), blockClick = useRef(0);
  const count = photos.length, index = count ? active % count : 0;
  const move = (delta: number) => setActive(value => (value + delta + count) % count);
  useEffect(() => {
    const node = root.current; if (!node) return;
    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { threshold: .2 }); observer.observe(node); return () => observer.disconnect();
  }, []);
  useEffect(() => {
    if (!visible || !playing || held || paused || count < 2) return;
    const media = matchMedia('(prefers-reduced-motion:reduce)'); let timer: ReturnType<typeof setInterval> | undefined;
    const sync = () => { if (timer) clearInterval(timer); timer = undefined; if (!document.hidden && !media.matches) timer = setInterval(() => setActive(value => (value + 1) % count), 3400); };
    sync(); document.addEventListener('visibilitychange', sync); media.addEventListener('change', sync);
    return () => { if (timer) clearInterval(timer); document.removeEventListener('visibilitychange', sync); media.removeEventListener('change', sync); };
  }, [visible, playing, held, paused, count]);
  if (!count) return null;
  return <div ref={root} className={styles.gallery} role="region" aria-roledescription="carousel" aria-label="International photo gallery"
    onKeyDown={event => { if (['ArrowLeft', 'ArrowRight'].includes(event.key)) { event.preventDefault(); move(event.key === 'ArrowRight' ? 1 : -1); } }}
    onFocusCapture={event => { if ((event.target as HTMLElement).matches(':focus-visible')) setHeld(true); }} onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setHeld(false); }}
    onPointerDown={event => { if (event.button === 0 && !(event.target as HTMLElement).closest('[data-gallery-controls]')) { pointer.current = { x: event.clientX, y: event.clientY, id: event.pointerId }; setHeld(true); } }}
    onPointerUp={event => {
      const start = pointer.current; pointer.current = null; setHeld(false);
      if (!start || start.id !== event.pointerId) return;
      const dx = event.clientX - start.x, dy = event.clientY - start.y;
      if (Math.abs(dx) > 35 && Math.abs(dx) > Math.abs(dy) * 1.15) { blockClick.current = Date.now() + 450; move(dx < 0 ? 1 : -1); }
    }} onPointerCancel={() => { pointer.current = null; setHeld(false); }} onDragStart={event => event.preventDefault()}
    onClickCapture={event => { if (Date.now() < blockClick.current && !(event.target as HTMLElement).closest('[data-gallery-controls]')) { event.preventDefault(); event.stopPropagation(); } }}>
    <div className={styles.galleryStage}>{photos.map((photo, i) => {
      const offset = (i - index + count) % count, position = offset > Math.floor(count / 2) ? offset - count : offset;
      return <button key={`${photo.src}-${i}`} type="button" className={styles.galleryPhoto} data-position={Math.max(-2, Math.min(2, position))} data-hidden={Math.abs(position) > 2}
        tabIndex={Math.abs(position) > 2 ? -1 : 0} aria-label={`Enlarge ${photo.alt || `international photograph ${i + 1}`}`} aria-current={i === index ? 'true' : undefined}
        onClick={() => { if (i === index) preview(i); else setActive(i); }}>
        <img src={photo.src} alt={photo.alt} loading="lazy" draggable={false} />
      </button>;
    })}</div>
    <div className={styles.galleryControls} data-gallery-controls>
      <div><button type="button" aria-label="Previous gallery photo" onClick={() => move(-1)}>‹</button><button type="button" aria-label={playing ? 'Pause photo slideshow' : 'Resume photo slideshow'} aria-pressed={!playing} onClick={() => setPlaying(value => !value)}>{playing ? 'Ⅱ' : '▶'}</button><button type="button" aria-label="Next gallery photo" onClick={() => move(1)}>›</button></div>
      <button type="button" className={styles.readMore} onClick={() => preview(index)}>View all <span aria-hidden="true">›</span></button>
    </div>
  </div>;
}

export default function InternationalPage() {
  const menuOpen = usePageMenuOpen();
  const root = useRef<HTMLElement>(null), revealed = useRef(new WeakSet<Element>());
  const [content, setContent] = useState<InternationalContent | null>(null), [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading'), [request, setRequest] = useState(0);
  const [opportunity, setOpportunity] = useState(0), [accordion, setAccordion] = useState<string | null>(null), [modal, setModal] = useState<Modal | null>(null), [directorExpanded, setDirectorExpanded] = useState(false);
  const id = useId();
  useEffect(() => {
    const controller = new AbortController(), timeout = setTimeout(() => controller.abort(), 20000); let mounted = true;
    setStatus('loading'); setContent(null);
    requestInternationalContent(controller.signal).then(value => { if (mounted) { setContent(value); setStatus('ready'); } }).catch(() => { if (mounted) setStatus('error'); }).finally(() => clearTimeout(timeout));
    return () => { mounted = false; clearTimeout(timeout); controller.abort(); };
  }, [request]);
  useEffect(() => {
    if (!root.current || matchMedia('(prefers-reduced-motion:reduce)').matches) return;
    const animations: Animation[] = [], observer = new IntersectionObserver(entries => entries.forEach(entry => {
      if (!entry.isIntersecting || revealed.current.has(entry.target)) return;
      revealed.current.add(entry.target); observer.unobserve(entry.target);
      animations.push(entry.target.animate([{ opacity: 0, transform: 'translateY(20px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: 650, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'backwards' }));
    }), { threshold: .08 });
    root.current.querySelectorAll('[data-international-reveal]').forEach(node => observer.observe(node));
    return () => { observer.disconnect(); animations.forEach(animation => animation.cancel()); };
  }, [status]);
  const showPhoto = useCallback((index: number) => { if (content) setModal({ kind: 'photos', photos: content.photos, index }); }, [content]);
  const configuredHero = hostelVideo(process.env.NEXT_PUBLIC_DGU_INTERNATIONAL_HERO_VIDEO_URL || '', 'Connecting Continents, Shaping Futures', asset('hero.jpeg'));
  const hero = content?.heroVideo || configuredHero;
  const chosenOpportunity = content?.opportunities[Math.min(opportunity, content.opportunities.length - 1)];
  const directorName=content?.director?.name || '',surnameAt=directorName.lastIndexOf(' ');
  const updates = (items: InternationalUpdate[], news = false) => <div className={news ? styles.newsList : styles.initiativeList} data-lenis-prevent="true" tabIndex={0} aria-label={news ? 'Global engagement news' : 'International initiatives'}>
    {items.map((item, index) => <article key={index} className={news ? styles.newsCard : styles.initiativeCard}>
      {!news && item.image && <img src={item.image} alt={item.title} loading="lazy" />}
      <div>{item.date && <time>{item.date}</time>}<h3>{item.title}</h3><p>{item.summary}</p>
        {(item.html || item.video) && <button type="button" className={styles.readMore} onClick={() => setModal({ kind: 'content', item })}>Read more <span aria-hidden="true">›</span></button>}
        {item.href && <a className={styles.updateLink} href={resolveSiteHref(item.href, item.title)}>Explore <span aria-hidden="true">↗</span></a>}
      </div>
    </article>)}
  </div>;

  return <main ref={root} className={styles.page} id="international-content">
    <div className={`${styles.shell} ${styles.heroWrap}`} data-navigation-opening>
      {hero ? <button className={styles.hero} type="button" onClick={() => setModal({ kind: 'video', video: { ...hero, title: 'Connecting Continents, Shaping Futures' } })} aria-label="Play Connecting Continents, Shaping Futures"><img src={asset('hero.jpeg')} alt="A globe connecting continents" /><Play /><span>{content?.tagline || 'Connecting Continents, Shaping Futures'}</span></button>
        : <div className={styles.hero}><img src={asset('hero.jpeg')} alt="A globe connecting continents" /><span>{content?.tagline || 'Connecting Continents, Shaping Futures'}</span></div>}
    </div>
    <PageTitleStrip title={content?.title || 'Office of International Affairs'} />
    {status !== 'ready' && <div className={`${styles.shell} ${styles.status}`} role={status === 'error' ? 'alert' : 'status'}>
      <p>{status === 'loading' ? 'Loading international opportunities…' : 'International information is temporarily unavailable.'}</p>
      {status === 'error' && <button type="button" onClick={() => setRequest(value => value + 1)}>Try again</button>}
    </div>}
    {content && <>
      <section className={`${styles.shell} ${styles.partnerships}`} data-international-reveal>
        {content.intro && <p className={styles.intro}>{content.intro}</p>}
        {!!content.partners.length && <InternationalCountryMap partners={content.partners} />}
        <div className={styles.stats}>{content.stats.map((stat, index) => <div key={index}>
          <svg viewBox="0 0 40 40" aria-hidden="true">{index === 0 ? <><circle cx="20" cy="16" r="12" /><ellipse cx="20" cy="16" rx="6" ry="12" /><path d="M8 16h24M10 10h20M10 22h20M4 31l8-6 7 6 6-6 11 7M4 31l8 5 7-5 6 5 11-4" /></> : <><path d="M5 15l9-5 8 5 9-5 5 15-9 7-10-5-11 4Z" /><path d="M24 12s-7-8-7-11a7 7 0 0 1 14 0c0 3-7 11-7 11Z" /><circle cx="24" cy="2" r="2" /></>}</svg>
          <strong>{stat.value}</strong><span>{stat.label}</span>
        </div>)}</div>
        {!!content.partners.length && <AutoSlider className={styles.partnerRail} label="Global partner university logos" duration={95} continuousOnMobile paused={!!modal || menuOpen}>
          {content.partners.map((partner, index) => <figure key={index}><img src={partner.src} alt={partner.name} loading="lazy" onError={event => { event.currentTarget.hidden = true; }} />{partner.name && <figcaption>{partner.name}</figcaption>}</figure>)}
        </AutoSlider>}
      </section>

      <section className={`${styles.shell} ${styles.opportunities}`} data-international-reveal>
        {!!content.opportunities.length && <>
          <SlidingTabList activeKey={opportunity} className={`${styles.tabs} ${styles.opportunityTabs}`} aria-label="International opportunities" onKeyDown={event => keyboardTabs(event, opportunity, content.opportunities.length, setOpportunity)}>
            {content.opportunities.map((item, index) => <button type="button" role="tab" key={index} id={`${id}-opportunity-${index}`} aria-selected={opportunity === index} aria-controls={`${id}-opportunity-panel`} tabIndex={opportunity === index ? 0 : -1} onClick={() => setOpportunity(index)}>{item.title}</button>)}
          </SlidingTabList>
          {chosenOpportunity && <div className={styles.opportunityPanel} role="tabpanel" id={`${id}-opportunity-panel`} aria-labelledby={`${id}-opportunity-${opportunity}`} key={opportunity}>
            <p>{chosenOpportunity.caption}</p>
            <div className={styles.opportunityCards}>{chosenOpportunity.cards.map((card, index) => <a key={index} href={resolveSiteHref(card.href, card.title)}>
              {card.image && <img src={card.image} alt="" loading="lazy" />}<h3>{card.title}</h3><span aria-hidden="true">›</span>
            </a>)}</div>
          </div>}
        </>}
        <ContentTabs items={content.pathways} label="International study pathways" />
      </section>

      {content.director && <section className={styles.director} data-international-reveal>
        <div className={styles.directorInner}>
          <div className={styles.directorPhoto}>{content.director.image && <img src={content.director.image} alt={content.director.name} loading="lazy" />}<svg viewBox="0 0 150 170" aria-hidden="true"><path d="M4 70 150 0v155l-46-33-38 48-31-22 39-51Z" /></svg></div>
          <div className={styles.directorCopy}><h2>{surnameAt>0 ? <><strong>{directorName.slice(0,surnameAt)}</strong>{directorName.slice(surnameAt)}</> : directorName}</h2><p className={styles.directorRole}>{content.director.role}</p>
            <div id={`${id}-director`} data-expanded={directorExpanded} className={styles.directorPreview}><ApiRichText html={content.director.html} /></div>
            <button type="button" className={styles.readMore} aria-expanded={directorExpanded} aria-controls={`${id}-director`} onClick={() => setDirectorExpanded(value => !value)}>{directorExpanded ? 'Read less' : 'Read more'} <span aria-hidden="true">›</span></button>
          </div>
          {content.director.video && <button type="button" className={styles.directorVideo} onClick={() => setModal({ kind: 'video', video: content.director!.video! })} aria-label="Play director's international affairs message"><img src={asset('director-poster.jpeg')} alt="" loading="lazy" /><Play /></button>}
        </div>
      </section>}

      {(content.initiatives.length > 0 || content.news.length > 0) && <section className={`${styles.shell} ${styles.updates}`} data-international-reveal>
        {!!content.initiatives.length && <div><h2 className={styles.underlined}>International Initiatives</h2>{updates(content.initiatives)}</div>}
        {!!content.news.length && <div><h2 className={styles.underlined}>Global Engagement:<small>News &amp; Highlights</small></h2>{updates(content.news, true)}</div>}
      </section>}

      {content.accreditation.html && <section className={`${styles.shell} ${styles.accreditation}`} data-international-reveal>
        <h2>{content.accreditation.title}</h2><ApiRichText html={content.accreditation.html} />
        {!!content.accreditation.logos.length && <AutoSlider className={styles.accreditationRail} label="Accreditations and memberships" duration={42} continuousOnMobile paused={!!modal || menuOpen}>
          {content.accreditation.logos.map((logo, index) => <figure key={index}><img src={logo.src} alt={logo.alt} loading="lazy" /></figure>)}
        </AutoSlider>}
      </section>}
      {content.erasmus.html && <section className={`${styles.shell} ${styles.erasmus}`} data-international-reveal><h2>{content.erasmus.title}</h2><ApiRichText html={content.erasmus.html} /></section>}
      {!!content.photos.length && <section className={`${styles.shell} ${styles.gallerySection}`} data-international-reveal><h2>Photo Gallery</h2><PhotoGallery photos={content.photos} paused={!!modal || menuOpen} preview={showPhoto} /></section>}

      {content.location.html && <section className={styles.location} data-international-reveal>
        <div className={`${styles.shell} ${styles.locationInner}`}>
          <div><h2>{content.location.title}</h2><h3>{content.location.subtitle}</h3><ApiRichText html={content.location.html} />
            <div className={styles.campusAccordions}>{content.location.accordions.map((item, index) => <div key={index}>
              <button type="button" id={`${id}-campus-toggle-${index}`} aria-expanded={accordion === `campus-${index}`} aria-controls={`${id}-campus-${index}`} onClick={() => setAccordion(value => value === `campus-${index}` ? null : `campus-${index}`)}>{item.title}<span aria-hidden="true">{accordion === `campus-${index}` ? '−' : '›'}</span></button>
              <div className={styles.accordionBody} data-open={accordion === `campus-${index}`} id={`${id}-campus-${index}`} role="region" aria-labelledby={`${id}-campus-toggle-${index}`} aria-hidden={accordion !== `campus-${index}`} inert={accordion !== `campus-${index}`}><div><ApiRichText html={item.html} /></div></div>
            </div>)}</div>
          </div>
          {content.location.video && <button type="button" className={styles.campusVideo} onClick={() => setModal({ kind: 'video', video: { ...content.location.video!, poster: asset('campus-poster.jpeg') } })} aria-label="Play Location and Campus video"><img src={asset('campus-poster.jpeg')} alt="An aerial view of the DGU campus in Dehradun" loading="lazy" /><Play /></button>}
        </div>
      </section>}

      <section className={`${styles.shell} ${styles.admissions}`} data-international-reveal>
        <h2 className={styles.barHeading}>Who Can Apply?</h2>
        {content.eligibilityIntro && <div className={styles.applyIntro}>
          <button type="button" id={`${id}-applicants-toggle`} aria-expanded={accordion === 'applicants'} aria-controls={`${id}-applicants-panel`} onClick={() => setAccordion(value => value === 'applicants' ? null : 'applicants')}>International applicants <span aria-hidden="true">{accordion === 'applicants' ? '−' : '+'}</span></button>
          <div className={styles.accordionBody} data-open={accordion === 'applicants'} id={`${id}-applicants-panel`} role="region" aria-labelledby={`${id}-applicants-toggle`} aria-hidden={accordion !== 'applicants'} inert={accordion !== 'applicants'}><div><ApiRichText html={content.eligibilityIntro} /></div></div>
        </div>}
        <ContentTabs items={content.eligibility} label="International admission guidance" />
        {content.process.title && <><h2 className={styles.barHeading}>{content.process.title}</h2><ol className={styles.process}>{content.process.steps.map((step, index) => <li key={index}><span>{String(index + 1).padStart(2, '0')}</span><div><h3>{step.title}</h3><p>{step.text}</p></div></li>)}</ol></>}
      </section>
      {!!content.impact.stories.length && <section className={`${styles.shell} ${styles.impact}`} data-international-reveal>
        <div><h2>{content.impact.title.split(/(\bJourneys\b|\bReal\b)/gi).map((word,index)=>/^(Journeys|Real)$/i.test(word) ? <strong key={index}>{word}</strong> : word)}</h2><p>{content.impact.caption}</p></div>
        <StepSlider label="Global journeys and student experiences" controls dots interval={5300} horizontalOnMobile paused={!!modal || menuOpen}>
          {content.impact.stories.map((story, index) => <figure key={index} className={styles.story}><blockquote><p>{story.quote}</p><cite>{story.name}</cite></blockquote>{story.image && <img src={story.image} alt={story.name} loading="lazy" />}</figure>)}
        </StepSlider>
      </section>}
      {content.additional.map((item, index) => <section key={index} className={`${styles.shell} ${styles.additional}`} data-international-reveal><ApiRichText html={item.html} scrollTables /></section>)}
    </>}
    {modal && <Preview value={modal} close={() => setModal(null)} change={index => setModal(value => value?.kind === 'photos' ? { ...value, index } : value)} />}
  </main>;
}
